                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 10 }} interval={0} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    unit="%"
                  />
                  <Tooltip />
                  <Bar
                    dataKey="sharePct"
                    name="Share %"
                    fill={NAVY}
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "swamp" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Did intensity fall ??? or did volume swamp it?"
            subtitle="Indices, 1990 = 100 ?? GCCA-style intensity vs USGS-order volume"
          >
            <div className="h-[380px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={[...INTENSITY_VS_VOLUME]}
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="volumeIndex"
                    name="Cement volume index"
                    fill={AMBER}
                    fillOpacity={0.25}
                    stroke={AMBER}
                  />
                  <Line
                    type="monotone"
                    dataKey="intensityIndex"
                    name="CO??? intensity index"
                    stroke={TEAL}
                    strokeWidth={2.5}
                    dot={false}
                  />
                  <Line
                    type="monotone"
                    dataKey="processMtIndex"
                    name="Process Mt index"
                    stroke={CLINKER}
                    strokeWidth={2}
                    strokeDasharray="4 4"
                    dot={false}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Clinker-to-cementitious path"
            subtitle="GCCA GNR-style ratio ?? ~10.7% relative improvement vs 1990"
          >
            <div className="h-[380px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={[...CLINKER_RATIO_PATH]}
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[70, 86]}
                    tick={{ fontSize: 11 }}
                    unit="%"
                  />
                  <Tooltip />
                  <Area
                    type="monotone"
                    dataKey="ratioPct"
                    name="Clinker ratio %"
                    fill={TEAL}
                    fillOpacity={0.2}
                    stroke={TEAL}
                    strokeWidth={2}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "regions" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Regional process CO???"
            subtitle="Asia-Pacific holds ~two-thirds of calcination emissions"
          >
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={[...REGION_PROCESS]}
                    dataKey="processMt"
                    nameKey="label"
                    cx="50%"
                    cy="50%"
                    innerRadius={68}
                    outerRadius={110}
                    paddingAngle={2}
                  >
                    {REGION_PROCESS.map((r, i) => (
                      <Cell
                        key={r.id}
                        fill={PIE_COLORS[i % PIE_COLORS.length]}
                      />
                    ))}
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Region Mt bars"
            subtitle="Same ledger as the donut ??? absolute process tonnes"
          >
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={[...REGION_PROCESS]}
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 10 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Bar dataKey="processMt" name="Process Mt" radius={[4, 4, 0, 0]}>
                    {REGION_PROCESS.map((r, i) => (
                      <Cell
                        key={r.id}
                        fill={PIE_COLORS[i % PIE_COLORS.length]}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "scatter" && (
        <ChartCard
          title="Process tonnes vs process intensity"
          subtitle="Bubble size ??? cement Mt ?? Vietnam sits with mid-pack intensity but top-3 producer volume"
        >
          <div className="h-[420px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 20, left: 8, bottom: 12 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="processMt"
                  name="Process Mt"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Process CO??? (Mt)",
                    position: "insideBottom",
                    offset: -4,
                    fontSize: 11,
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="intensityKgPerTCement"
                  name="Intensity"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "kg CO??? / t cement",
                    angle: -90,
                    position: "insideLeft",
                    fontSize: 11,
                  }}
                />
                <ZAxis type="number" dataKey="cementMt" range={[60, 400]} />
                <Tooltip cursor={{ strokeDasharray: "3 3" }} />
                <Scatter name="Producers" data={scatter} fill={CLINKER}>
                  {scatter.map((p) => (
                    <Cell
                      key={p.id}
                      fill={
                        p.id === "china" ||
                        p.id === "india" ||
                        p.id === "vietnam"
                          ? CLINKER
                          : SLATE
                      }
                    />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

