  if (n >= 100) return `${Math.round(n)} Mt`;
  if (n >= 10) return `${n.toFixed(0)} Mt`;
  return `${n.toFixed(1)} Mt`;
}

export function fmtPct(n: number): string {
  return `${n.toFixed(1)}%`;
}

