const start = t.indexOf('id: "cement-clinker-process-emissions-by-country-2026"');
const end = t.indexOf('id: "spot-container-freight-vs-blank-sailings-2026"', start + 10);
const block = t.slice(start, end);
const m = block.match(/content: `([\s\S]*?)`,\s*\},/);
